    public void testGet_WhenIndexIsFound() {
        // Test getting a value by name that exists in the mapping
        String result = record.get("header1");
        Assert.assertEquals("value1", result);
    }


@Test
    public void testGet_WhenNameIsMappedToIndexLargerThanValuesLength() {
        // Test when the index is larger than the values length (should throw exception)
        mapping.put("header4", 5);
        String result = record.get("header4");
        // We expect an IllegalArgumentException
    }


@Test
    public void testGet_WhenIndexIsNotFound() {
        // Test getting a value by name that does not exist in the mapping
        String result = record.get("nonexistent");
        Assert.assertNull(result);
    }


@Test
    public void testGet_WhenNameIsMappedToIndexEqualToZero() {
        // Test when the index is 0 (should work)
        mapping.put("header4", 0);
        String result = record.get("header" + 4); // Using a different name to avoid conflict
        Assert.assertEquals(values[0], result);
    }


@Test
    public void testGet_WhenNameIsMappedToIndexThree() {
        // Test when the index is 3 (should throw exception because array length is 3, index 3 is out of bounds)
        mapping.put("header4", 3);
        String result = record.get("header" + 4);
        // We expect an IllegalArgumentException
    }


@Test
    public void testGet_WhenIndexIsOutOfBounds() {
        // Test when the index is out of bounds (should throw exception)
        mapping.put("header4", 10); // index 10 is out of bounds for an array of size 3
        String result = record.get("header4");
        // We expect an ArrayIndexOutOfBoundsException to be caught and rethrown as IllegalArgumentException
        Assert.assertNull(result); // This won't work because the exception is thrown
        // Instead, we should use ExpectedException rule or try-catch
    }


@Test
    public void testGet_WhenNameIsMappedToNegativeIndex() {
