        mapping.put("header4", -1);
        String result = record.get("header4");
        // We expect an IllegalArgumentException because the index is negative and out of bounds
    }


@Test
    public void testGet_WhenNameIsMappedToIndexTwo() {
        // Test when the index is 2 (should work)
        mapping.put("header4", 2);
        String result = record.get("header" + 4);
        Assert.assertEquals(values[2], result);
    }


@Test
    public void testGet_WhenNameIsMappedToIndexEqualToValuesLength() {
        // Test when the index is equal to the values length (should throw exception because index starts at 0)
        // For an array of length 3, index 3 is out of bounds (since indices are 0 to 2)
        mapping.put("header4", 3);
        String result = record.get("header4");
        // We expect an IllegalArgumentException
    }


@Test
    public void testGet_WhenNameIsMappedToIndexOne() {
        // Test when the index is 1 (should work)
        mapping.put("header4", 1);
        String result = record.get("header" + 4);
        Assert.assertEquals(values[1], result);
    }


@Test
    public void testGet_WhenIndexIsNull() {
        // Test when mapping returns null for the given name
        mapping.put("header4", null); // This is not allowed in the constructor, but we can test the behavior
        String result = record.get("header4");
        Assert.assertNull(result);
    }


